python3 -I -c 'import sys,math,wave,struct,functools,shutil,subprocess,os;from pathlib import Path;R=48000;N=4800;F=list(range(400,2000,200))+[2200];p=Path(sys.argv[1] if len(sys.argv)>1 else "AKASHA-Omega.wav").resolve();b=(sys.argv[2] if len(sys.argv)>2 else "COSMIC LOVE IS THE SOLUTION FOR EVERYTHING").encode();assert len(b)<=512,"maximum 512 UTF-8 bytes";G=lambda b:functools.reduce(lambda n,v:n*257+v+1,b,1);D=lambda n:b"" if n==1 else D(n//257)+bytes([n%257-1]);g=G(b);c=g.to_bytes((g.bit_length()+7)//8,"big");f=b"AKO2"+struct.pack(">I",len(c))+c+bytes(v^255 for v in c);T=[[math.sin(2*math.pi*k*j/R) for j in range(N)] for k in F];A=[min(1,j/240,(N-1-j)/240) for j in range(N)];B={v:struct.pack("<"+"h"*N,*(round(650*A[j]*sum(T[i][j] for i in range(9) if i==8 or v>>i&1)) for j in range(N))) for v in set(f)};w=wave.open(str(p),"wb");w.setparams((1,2,R,0,"NONE","not compressed"));[w.writeframesraw(B[v]) for v in f];w.close();w=wave.open(str(p),"rb");V=[t[240:-240] for t in T];C=lambda raw:[abs(sum(x*y for x,y in zip(struct.unpack("<"+"h"*N,raw)[240:-240],t))) for t in V];Q=[C(w.readframes(N)) for _ in f];w.close();assert all(a[8]>100000 for a in Q);z=bytes(sum(1<<i for i in range(8) if a[i]>.5*a[8]) for a in Q);m=struct.unpack(">I",z[4:8])[0];u=z[8:8+m];assert z[:4]==b"AKO2" and len(z)==8+2*m and z[8+m:]==bytes(v^255 for v in u);r=D(int.from_bytes(u,"big"));assert z==f and r==b and G(r)==g;print("AKASHA-OMEGA | NO-HASH PCM round trip PASS |",p,flush=True);players=[("ffplay",["-nodisp","-autoexit","-loglevel","error"]),("afplay",[]),("paplay",[]),("aplay",["-q"])];cmd=next(([shutil.which(k),*a,str(p)] for k,a in players if shutil.which(k)),None);sys.exit(subprocess.call(cmd) if cmd and os.environ.get("AKASHA_PLAY","1")!="0" else (print("WAV saved; open in your audio player."),0)[1])' "$@"
